ltest=[{"n":i+1,"question_zh":"（听录音）"+s,"image":img(im),"options":["✓","✗"],"script_zh":s,"answer":a,"explanation_mn":e} for i,(s,a,im,e) in enumerate(JT)]

def _mk(n,q,opts,ans,expl,seed,extra=None):
    o,_=shuffle(opts,ans,seed); d={"n":n,"question_zh":q,"options":o,"answer":ans,"explanation_mn":expl}
    if extra: d.update(extra)
    return d
def RD(n,q,qmn,opts,ans,expl,seed): return _mk(n,q,opts,ans,expl,seed,{"question_mn":qmn})
def FT(n,q,py,ans,dis,expl,seed): return _mk(n,q.replace("（　　）","（"+py+"）"),[ans]+dis,ans,expl,seed,{"pinyin_hint":py})
def CH(n,zh,mn,ans,expl): return {"n":n,"question_zh":zh,"question_mn":mn,"image":img(f"c{n}"),"options":["Зүүн зураг","Баруун зураг"],"answer":ans,"explanation_mn":expl}

